INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Schätzung von Personal- und Materialbedarf nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen Planung"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Schätzung von Personal- und Materialbedarf?', 3, '[{"text": "Ressourcenbedarf planen", "correct": true, "because": "Sichert Projektumsetzung"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Planung im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Schätzung von Personal- und Materialbedarf?', 5, '[{"text": "Personalstunden", "correct": true, "because": "Misst Arbeitsaufwand"}, {"text": "Materialkosten", "correct": true, "because": "Berechnet Ressourcen"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ressourcenbedarf schätzen optimiert Projekte. b) Es ist nur für den Projektstart nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Durchgehende Anpassung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Schätzung von Personal- und Materialbedarf?', 4, '[{"text": "Projektphasen", "correct": false, "because": "Bestimmen Bedarf"}, {"text": "Ressourcenkosten", "correct": false, "because": "Wichtig für Budget"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Schätzung von Personal- und Materialbedarf auch Zeitpläne berücksichtigt?', 2, '[{"text": "Ja", "correct": true, "because": "Zeit beeinflusst Ressourcen"}, {"text": "Nein", "correct": false, "because": "Teil der Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist typisch für die Schätzung von Personal- und Materialbedarf?', 3, '[{"text": "Aufgabenliste", "correct": true, "because": "Definiert Ressourcenbedarf"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen die Schätzung von Personal- und Materialbedarf?', 5, '[{"text": "Bottom-Up-Schätzung", "correct": true, "because": "Detaillierte Planung"}, {"text": "Analogieschätzung", "correct": true, "because": "Nutzt Erfahrungswerte"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ressourcenbedarf schätzen spart Kosten. b) Es ist nur für Personal nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Material bedacht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Schätzung von Personal- und Materialbedarf?', 4, '[{"text": "Projektumfang", "correct": false, "because": "Bestimmt Bedarf"}, {"text": "Budgetplan", "correct": false, "because": "Grenzen festlegen"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Schätzung von Personal- und Materialbedarf nur für den Anfang nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Anpassung während des Projekts"}, {"text": "Ja", "correct": false, "because": "Kontinuierlich nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Schätzung von Personal- und Materialbedarf?', 4, '[{"text": "Projektzeitplan", "correct": true, "because": "Bestimmt Ressourcennutzung"}, {"text": "Aufgabenkomplexität", "correct": true, "because": "Beeinflusst Bedarf"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Schätzung von Personal- und Materialbedarf ungenau ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Mit Methoden präzise möglich"}, {"text": "Ja", "correct": false, "because": "Genauigkeit erreichbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Schätzung von Personal- und Materialbedarf?', 3, '[{"text": "Genauigkeit", "correct": true, "because": "Sichert Ressourcenplanung"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Schriftgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ressourcenbedarf schätzen hilft beim Budgetieren. b) Es ist nur für Material nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Personal bedacht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Schätzung von Personal- und Materialbedarf?', 5, '[{"text": "Kostenkontrolle", "correct": true, "because": "Verhindert Überausgaben"}, {"text": "Ressourcenzuweisung", "correct": true, "because": "Optimiert Einsatz"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Schätzung von Personal- und Materialbedarf unwichtig?', 3, '[{"text": "Projektziele", "correct": false, "because": "Bestimmen Bedarf"}, {"text": "Ressourcenverfügbarkeit", "correct": false, "because": "Beeinflusst Planung"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Schätzung von Personal- und Materialbedarf nur für große Teams?', 3, '[{"text": "Nein", "correct": true, "because": "Auch kleine Teams planen"}, {"text": "Ja", "correct": false, "because": "Universell nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Schätzung von Personal- und Materialbedarf angepasst werden sollte?', 2, '[{"text": "Ja", "correct": true, "because": "Änderungen im Projekt"}, {"text": "Nein", "correct": false, "because": "Flexibilität nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel wähle ich für die Schätzung von Personal- und Materialbedarf?', 4, '[{"text": "Bottom-Up-Schätzung", "correct": true, "because": "Detaillierte Planung"}, {"text": "Zufällige Daten", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Planungsfokus"}]');
